def maximum_absolute_subarray_sum(nums):
 prefix=0;smallest=largest=0;answer=0
 for value in nums:
  prefix+=value;answer=max(answer,abs(prefix-smallest),abs(prefix-largest));smallest=min(smallest,prefix);largest=max(largest,prefix)
 return answer

